n// ============================================================================\n\nmodel Task {\n  id       String @id @default(uuid())\n  taskId   String // ID da task no BPMN\n  name     String\n  lane     String // Responsável\n  status   String // \"pending\", \"in_progress\", \"completed\", \"failed\"\n  priority Int    @default(5)\n\n  processInstanceId String\n  processInstance   ProcessInstance @relation(fields: [processInstanceId], references: [id])\n\n  assignedTo  String? // userId\n  startedAt   DateTime?\n  completedAt DateTime?\n  durationMs  Int?\n\n  input  Json? // Dados de entrada\n  output Json? // Dados de saída\n  error  String?\n\n  @@index([processInstanceId])\n  @@index([status])\n  @@index([assignedTo])\n  @@map(\"tasks\")\n}\n\n// ============================================================================\n// CAMPANHAS (META/GOOGLE ADS)\n// ============================================================================\n\nmodel Campaign {\n  id         String @id @default(uuid())\n  externalId String @unique // ID do Meta/Google\n  platform   String // \"meta\", \"google\"\n  name       String\n  status     String // \"active\", \"paused\", \"archived\"\n\n  clientId String\n  client   Client @relation(fields: [clientId], references: [id])\n\n  budget Float\n  spent  Float @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relações\n  metrics Metric[]\n\n  @@index([clientId])\n  @@index([platform])\n  @@map(\"campaigns\")\n}\n\n// ============================================================================\n// MÉTRICAS DIÁRIAS\n// ============================================================================\n\nmodel Metric {\n  id   String   @id @default(uuid())\n  date DateTime\n\n  clientId String\n  client   Client @relation(fields: [clientId], references: [id])\n\n  campaignId String?\n  campaign   Campaign? @relation(fields: [campaignId], references: [id])\n\n  // Métricas\n  impressions Int   @default(0)\n  clicks      Int   @default(0)\n  conversions Int   @default(0)\n  spent       Float @default(0)\n  revenue     Float @default(0)\n\n  // Calculados\n  ctr  Float? // Click-through rate\n  cpc  Float? // Cost per click\n  cpa  Float? // Cost per acquisition\n  roas Float? // Return on ad spend\n\n  createdAt DateTime @default(now())\n\n  @@unique([clientId, campaignId, date])\n  @@index([clientId])\n  @@index([date])\n  @@map(\"metrics\")\n}\n\n// ============================================================================\n// AUDIT TRAIL\n// ============================================================================\n\nmodel AuditEvent {\n  id        String @id @default(uuid())\n  eventType String\n\n  processId String?\n  clientId  String\n  userId    String\n  userRole  String\n\n  resource Json // { type, id, name }\n  action   String\n  changes  Json? // { before, after }\n\n  metadata        Json // { ipAddress, userAgent, etc }\n  complianceFlags Json // { gdpr, lgpd, etc }\n\n  timestamp DateTime @default(now())\n\n  @@index([clientId])\n  @@index([eventType])\n  @@index([timestamp])\n  @@map(\"audit_events\")\n}\n\n// ============================================================================\n// USUÁRIOS DO SISTEMA\n// ============================================================================\n\nmodel User {\n  id           String @id @default(uuid())\n  email        String @unique\n  name         String\n  role         String // \"admin\", \"gestor_trafego\", \"cs\", etc\n  passwordHash String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"users\")\n}\n\n// ============================================================================\n// LOCKS DISTRIBUÍDOS\n// ============================================================================\n\nmodel Lock {\n  id           String @id @default(uuid())\n  resourceType String // \"campaign\", \"client\", etc\n  resourceId   String\n  clientId     String\n  holderId     String // process_X.Y_instance_NNN\n  holderType   String // \"optimization\", \"offboarding\", etc\n\n  priority Int\n  status   String // \"active\", \"expired\", \"released\"\n\n  acquiredAt DateTime @default(now())\n  expiresAt  DateTime\n\n  @@unique([resourceType, resourceId])\n  @@index([status])\n  @@index([expiresAt])\n  @@map(\"locks\")\n}\n\n// ============================================================================\n// VERSÕES DE PROCESSOS\n// ============================================================================\n\nmodel ProcessVersion {\n  id        String @id @default(uuid())\n  processId String // \"5.2\", \"6.1\", etc\n  version   String // \"1.0.0\", \"2.0.0\", etc\n  status    String // \"active\", \"deprecated\", \"archived\"\n\n  description     String\n  breaking        Boolean @default(false)\n  rollbackVersion String?\n\n  deployedAt   DateTime  @default(now())\n  deprecatedAt DateTime?\n\n  metadata Json // { author, changelog, testsPass, approvedBy }\n\n  @@unique([processId, version])\n  @@index([processId])\n  @@index([status])\n  @@map(\"process_versions\")\n}\n",
